    for(E e: tour){
        vertexEdges.computeIfAbsent(graph.getEdgeSource(e), k->new ArrayList<>()).add(e);
        vertexEdges.computeIfAbsent(graph.getEdgeTarget(e), k->new ArrayList<>()).add(e);
    }
    // start from any edge
    E startEdge = tour.iterator().next();
    V startVertex = graph.getEdgeSource(startEdge);
    V currentVertex = startVertex;
    E prevEdge = null;
    while(edgeList.size() < tour.size()){
        List<E> incid = vertexEdges.get(currentVertex);
        if(incid == null){ break; }
        E nextEdge = null;
        for(E e: incid){
