        edgeList.add(nextEdge);
        prevEdge = nextEdge;
        // switch to opposite vertex
        V t1 = graph.getEdgeSource(nextEdge);
        V t2 = graph.getEdgeTarget(nextEdge);
        currentVertex = t1.equals(currentVertex) ? t2 : t1;
    }
    // Build vertex list
