        V t2 = graph.getEdgeTarget(e);
        currentVertex = t1.equals(currentVertex) ? t2 : t1;
        vertexList.add(currentVertex);
    }
    double weight = 0.0;
    for(E e: edgeList){
        weight += graph.getEdgeWeight(e);
    }
    V endVertex = vertexList.get(vertexList.size() - 1);
    return new org.jgrapht.graph.DefaultGraphPath<>(graph, startVertex, endVertex, weight, vertexList, edgeList);
